package com.aoo.bcg.common.cache;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class CacheInvalidationCoordinatorTest{@Test void invalidatesEveryBackendForRoomVersionAndLogout(){var events=new ArrayList<CacheInvalidationCoordinator.Invalidation>();var coordinator=new CacheInvalidationCoordinator(List.of(events::add,events::add));coordinator.roomEnded(7);coordinator.playVersionUnpublished(10,"v2");coordinator.accountLoggedOut(9);assertEquals(6,events.size());assertEquals(2,events.stream().filter(value->value.scope()==CacheInvalidationCoordinator.Scope.ROOM).count());assertEquals(2,events.stream().filter(value->value.scope()==CacheInvalidationCoordinator.Scope.PLAY_VERSION).count());assertEquals(2,events.stream().filter(value->value.scope()==CacheInvalidationCoordinator.Scope.ACCOUNT).count());}@Test void backendFailureIsVisibleAfterOtherBackendsRun(){var calls=new ArrayList<String>();var coordinator=new CacheInvalidationCoordinator(List.of(value->{calls.add("failed");throw new Exception("down");},value->calls.add("healthy")));assertThrows(IllegalStateException.class,()->coordinator.roomEnded(1));assertEquals(List.of("failed","healthy"),calls);}}
